//! The strided offset and unravel spellings that emitters share (`cfamily::strided_offset_expr`,
//! `cfamily::unravel_decomp`, 0.38.1).
//!
//! `baracuda-cuda-emit` and `openclownfish-clc` each kept a private copy; these golden strings follow
//! the format strings of those copies (read, not run, at their `origin/main`, 2026-10-31), so an
//! emitter that switches to the shared one should change no generated byte. Each emitter's own tests
//! are the check on that, when it switches.

use unpopped::cfamily::{strided_offset_expr, unravel_decomp};
use unpopped_vocab::AxisMask;

fn mask(axes: &[u8]) -> AxisMask {
    let mut m = AxisMask::EMPTY;
    for &a in axes {
        m.set(a);
    }
    m
}

#[test]
fn offset_skips_broadcast_axes_and_names_the_stride_array() {
    assert_eq!(
        strided_offset_expr(mask(&[]), "c", "s0", 3, None),
        "c0*s0_0 + c1*s0_1 + c2*s0_2"
    );
    assert_eq!(
        strided_offset_expr(mask(&[1]), "c", "s0", 3, None),
        "c0*s0_0 + c2*s0_2",
        "a broadcast axis drops out"
    );
    assert_eq!(
        strided_offset_expr(mask(&[0, 1]), "c", "so", 2, None),
        "0",
        "every axis broadcast: the offset is the constant 0"
    );
    assert_eq!(strided_offset_expr(mask(&[]), "c", "s0", 0, None), "0");
}

#[test]
fn offset_through_a_permute_pairs_each_axis_with_the_permuted_stride() {
    // A transpose read: iteration axis 0 reads stride 1 and axis 1 reads stride 0.
    assert_eq!(
        strided_offset_expr(mask(&[]), "c", "s1", 2, Some(&[1, 0])),
        "c0*s1_1 + c1*s1_0"
    );
}

#[test]
fn offset_takes_any_coordinate_prefix() {
    assert_eq!(
        strided_offset_expr(mask(&[1]), "uc", "s2", 2, None),
        "uc0*s2_0"
    );
}

#[test]
fn unravel_declares_each_axis_last_fastest() {
    let got = unravel_decomp(
        (0..2).rev(),
        "    ",
        "idx",
        "long long",
        |a| format!("c{a}"),
        |a| format!("shape{a}"),
        false,
    );
    assert_eq!(
        got,
        "    long long c1 = idx % shape1; idx /= shape1;\n    long long c0 = idx % shape0; idx /= shape0;\n"
    );
}

#[test]
fn unravel_guards_an_empty_axis_and_takes_the_targets_wide_type() {
    let got = unravel_decomp(
        [0usize],
        "",
        "lin",
        "long",
        |a| format!("c{a}"),
        |a| format!("shape.v[{a}]"),
        true,
    );
    assert_eq!(
        got,
        "long c0 = (shape.v[0] == 0) ? 0 : (lin % (long)shape.v[0]); if (shape.v[0] != 0) lin /= (long)shape.v[0];\n"
    );
    let none = unravel_decomp(
        [],
        "  ",
        "lin",
        "long",
        |_| String::new(),
        |_| String::new(),
        false,
    );
    assert_eq!(none, "", "no axes, no statements");
}
